const StencilEntry* lookup_stencil(uint32_t opcode, uint32_t subop, bool Rc,
                                   int rd_idx, int ra_idx, int rb_idx) {
    if (rd_idx < 0 || rd_idx >= 5 || ra_idx < 0 || ra_idx >= 5 || rb_idx < 0 || rb_idx >= 5) return nullptr;
    uint32_t key = (opcode << 16) | (subop & 0xFFFF);
    auto it = s_lookup_map.find(key);
    if (it == s_lookup_map.end()) return nullptr;
    const auto& info = it->second;
    int rc_idx = (Rc && info.has_Rc) ? 1 : 0;
    if (info.has_rb) {
        size_t idx = (rc_idx * 5 * 5 * 5) + (rd_idx * 5 * 5) + (ra_idx * 5) + rb_idx;
        return &info.table[idx];
    } else {
        size_t idx = (rc_idx * 5 * 5) + (rd_idx * 5) + ra_idx;
        return &info.table[idx];
    }
}

size_t get_total_stencil_count() { return 15100; }
size_t get_total_stencil_bytes() { return sizeof(g_stencil_pool); }
const uint8_t* get_stencil_pool_base() { return g_stencil_pool; }
